package com.flansmod.common;

/** Observed R-key edges only. No desktop input is generated by this clock. */
public final class ReloadKeyState {
	public static final int DOUBLE_TICKS=6,HOLD_TICKS=4;
	public static final int NORMAL=1,SPECIAL=2,HOLD=4,RELEASE=8;
	private Object item;
	private int slot=-1,tick,firstPress=-1,heldTicks;
	private boolean wasDown,compressing,awaitRelease;
	public int update(boolean down,boolean magazine,int selected,Object heldItem) {
		return update(down,magazine,selected,heldItem,0);
	}
	public int update(boolean down,boolean magazine,int selected,Object heldItem,int observedPresses) {
		int result=0;tick++;
		if(slot!=selected || item!=heldItem) {
			boolean stillDown=wasDown && down;
			result=reset();slot=selected;item=heldItem;
			awaitRelease=stillDown;
		}
		if(heldItem==null) return result;
		if(awaitRelease) { if(!down) awaitRelease=false;wasDown=down;return result; }
		if(magazine) {
			if(down) {
				if(++heldTicks>=HOLD_TICKS && !compressing) { compressing=true;result|=HOLD; }
			} else {
				heldTicks=0;
				if(compressing) { compressing=false;result|=RELEASE; }
			}
		} else {
			int presses=observedPresses>0?observedPresses:down && !wasDown?1:0;
			for(int i=0;i<presses;i++) {
				if(firstPress>=0 && tick-firstPress<=DOUBLE_TICKS) { result|=SPECIAL;firstPress=-1; }
				else firstPress=tick;
			}
			if(firstPress>=0 && tick-firstPress>=DOUBLE_TICKS) { result|=NORMAL;firstPress=-1; }
		}
		wasDown=down;return result;
	}
	public int reset() {
		int result=compressing?RELEASE:0;
		item=null;slot=-1;firstPress=-1;heldTicks=0;wasDown=compressing=awaitRelease=false;
		return result;
	}
}
